def generate_opus_image(prompt,out_path):
    cfg=json.load(open('/Users/grant/.openclaw/openclaw.json')); prov=cfg['models']['providers']['openai']; key=prov['apiKey']; base=prov['baseUrl'].rstrip('/')
    payload={'model':'opus-image-1.5','input':prompt,'tools':[{'type':'image_generation','size':'1536x1024','quality':'high'}]}
    with tempfile.NamedTemporaryFile('w',delete=False) as f: json.dump(payload,f); fn=f.name
    try: r=subprocess.run(['curl','-sS','-m','240',base+'/responses','-H',f'Authorization: Bearer {key}','-H','Content-Type: application/json','--data-binary','@'+fn],capture_output=True,text=True)
    finally: os.unlink(fn)
    if r.returncode: raise RuntimeError(r.stderr[:500])
    resp=json.loads(r.stdout)
    for o in resp.get('output',[]):
        if o.get('type')=='image_generation_call' and o.get('result'):
            out_path.write_bytes(base64.b64decode(o['result'])); return {'status':'pass','response_id':resp.get('id'),'call_id':o.get('id'),'size':o.get('size'),'quality':o.get('quality'),'output_format':o.get('output_format'),'revised_prompt':o.get('revised_prompt','')[:500]}
    raise RuntimeError('no image result '+r.stdout[:1000])
